"""## 1. Load raw dataset and verify schema"""

import os, sys, json, math, warnings, urllib.request
from pathlib import Path
import numpy as np, pandas as pd, matplotlib.pyplot as plt
from scipy.stats import norm
from sklearn.model_selection import train_test_split
from sklearn.compose import ColumnTransformer
from sklearn.preprocessing import OneHotEncoder, StandardScaler
from sklearn.impute import SimpleImputer
from sklearn.pipeline import Pipeline
from sklearn.linear_model import LinearRegression, LogisticRegression
from sklearn.metrics import confusion_matrix, accuracy_score, roc_auc_score
import statsmodels.api as sm
from docx import Document
from docx.shared import Inches, Pt, RGBColor
warnings.filterwarnings('ignore', category=FutureWarning)
SEED=843
np.random.seed(SEED)
OUT=Path('cset485_german_843_outputs');OUT.mkdir(exist_ok=True)
urls=['https://archive.ics.uci.edu/ml/machine-learning-databases/statlog/german/german.data',
      'https://raw.githubusercontent.com/selva86/datasets/master/GermanCredit.csv']
raw=None;source=None
for url in urls:
    try:
        path=OUT/'download.tmp'
        urllib.request.urlretrieve(url,path)
        if 'german.data' in url:
            t=pd.read_csv(path,sep=r'\s+',header=None)
            if t.shape==(1000,21):raw=t;source=url;break
        # The fallback dataset may have a different schema; never silently use it.
    except Exception as e:
        print('Attempt failed:',url,repr(e)[:130])
if raw is None:
    from google.colab import files
    print('Automatic UCI download failed. Please upload original german.data from the UCI dataset link.')
    incoming=files.upload()
    candidate=next(iter(incoming))
    raw=pd.read_csv(candidate,sep=r'\s+',header=None)
    source='Manual UCI german.data upload'
assert raw.shape==(1000,21),f'Expected original German Credit 1000x21; received {raw.shape}'
cols=['checking_status','duration','credit_history','purpose','credit_amount','savings','employment','installment_rate','personal_status_sex','other_debtors','residence_since','property','age','other_installment_plans','housing','existing_credits','job','people_liable','telephone','foreign_worker','credit_class']
raw.columns=cols
assert set(raw.credit_class.unique())=={1,2}
df=raw.copy();df['approve']=(df.credit_class==1).astype(int);df=df.drop(columns='credit_class')
df['sex_group']=np.where(df.personal_status_sex.isin(['A91','A93','A94']),'Male','Female')
df['age_group']=np.where(df.age<30,'Under 30','30 and older')
print('Source:',source,'Shape:',df.shape,'Approval proxy counts:',df.approve.value_counts().to_dict())
display(df.head())

"""## 2. Data audit, train/test split, encoding and scale"""

numeric=['duration','credit_amount','installment_rate','residence_since','age','existing_credits','people_liable']
categorical=[c for c in cols[:-1] if c not in numeric]
# Derived demographics are reserved for disaggregated evaluation, not duplicated as model predictors.
features=numeric+categorical
X=df[features].copy();y=df.approve
idx_train,idx_test=train_test_split(np.arange(len(df)),test_size=.30,random_state=SEED,stratify=y)
Xtr,Xte=X.iloc[idx_train],X.iloc[idx_test]
ytr,yte=y.iloc[idx_train],y.iloc[idx_test]
test_df=df.iloc[idx_test].copy();train_df=df.iloc[idx_train].copy()
missing=df[features].isna().sum();iqr_outliers={}
for c in numeric:
 q1,q3=Xtr[c].quantile([.25,.75]);iqr=q3-q1
 iqr_outliers[c]=int(((Xtr[c]<q1-1.5*iqr)|(Xtr[c]>q3+1.5*iqr)).sum())
# No deletion or winsorization: extreme cases may be policy-relevant. Train-only scaling and imputation avoid leakage.
num_pipe=Pipeline([('impute',SimpleImputer(strategy='median')),('scale',StandardScaler())])
cat_pipe=Pipeline([('impute',SimpleImputer(strategy='most_frequent')),('encode',OneHotEncoder(handle_unknown='ignore',drop='first',sparse_output=False))])
prep=ColumnTransformer([('num',num_pipe,numeric),('cat',cat_pipe,categorical)],verbose_feature_names_out=False)
Ztr=prep.fit_transform(Xtr);Zte=prep.transform(Xte)
feature_names=list(prep.get_feature_names_out())
print('Missing:',missing.to_dict());print('Training IQR outlier counts:',iqr_outliers)
print('Train/test sizes:',len(idx_train),len(idx_test),'Encoded feature count:',len(feature_names))

"""## 3. Part 1 — OLS vs logistic thresholding"""

ols=LinearRegression().fit(Ztr,ytr)
logit=LogisticRegression(max_iter=3000,solver='lbfgs',C=1.0).fit(Ztr,ytr)
ols_pred=ols.predict(Zte);prob=logit.predict_proba(Zte)[:,1]
med=float(np.median(ols_pred))
flag_A=(ols_pred>=med).astype(int);flag_B=(prob>=.5).astype(int)
cm=confusion_matrix(flag_A,flag_B,labels=[0,1])
mismatch=int((flag_A!=flag_B).sum());mismatch_pct=100*mismatch/len(yte)
print('Rows A=OLS median labels [0,1]; columns B=Logistic 0.5 [0,1]')
print(cm,'Mismatch:',mismatch,f'({mismatch_pct:.2f}%)','OLS median:',med)
print('OLS binary proxy accuracy:',accuracy_score(yte,flag_A),'Logistic accuracy:',accuracy_score(yte,flag_B),'Logistic AUC:',roc_auc_score(yte,prob))
pd.DataFrame(cm,index=['OLS < median','OLS >= median'],columns=['Logistic < .5','Logistic >= .5']).to_csv(OUT/'part1_confusion.csv')

"""## 4. Part 2.1 — Subgroup coefficients, statistical comparisons"""

# Use the exact SAME encoding/scaling across full and subgroup fits; no subgroup-specific transformations.
# For coefficient uncertainty, fit unpenalized binomial GLMs with 95% Wald intervals.
# GLM is used for inference; sklearn regularized logistic is the main prediction model.
Ztrain=pd.DataFrame(Ztr,index=Xtr.index,columns=feature_names)
# Sex-status dummy columns are constant within subgroups; omit from ALL inference fits to avoid rank-deficient subgroup models.
infer_features=[v for v in feature_names if not v.startswith('personal_status_sex_')]
Ztrain=Ztrain[infer_features]
subgroups=train_df['sex_group']
def glm_fit(mat,target):
    return sm.GLM(np.asarray(target),sm.add_constant(np.asarray(mat),has_constant='add'),family=sm.families.Binomial()).fit(maxiter=200)
def estimates(fit,names):
    conf=np.asarray(fit.conf_int())
    return pd.DataFrame({'coef':fit.params[1:],'ci_low':conf[1:,0],'ci_high':conf[1:,1],'se':fit.bse[1:],'p':fit.pvalues[1:]},index=names)
full_glm=glm_fit(Ztrain,ytr)
fits={'Full':full_glm}
for group in ['Male','Female']:
    mask=(subgroups==group).to_numpy()
    fits[group]=glm_fit(Ztrain.to_numpy()[mask],ytr.to_numpy()[mask])
all_est={k:estimates(f,infer_features) for k,f in fits.items()}
# Prioritize interpretable continuous predictors; seek statistically significant between-group difference.
keys=['duration','credit_amount','installment_rate','age','existing_credits']
comparisons=[]
for key in keys:
    a,b=all_est['Male'].loc[key],all_est['Female'].loc[key]
    diff=a['coef']-b['coef'];se=np.sqrt(a['se']**2+b['se']**2)
    p=2*norm.sf(abs(diff/se)) if se>0 else np.nan
    comparisons.append((key,all_est['Full'].loc[key,'coef'],a['coef'],b['coef'],p))
comp=pd.DataFrame(comparisons,columns=['predictor','full_coef','male_coef','female_coef','difference_p'])
comp=comp.sort_values('difference_p')
selected=comp.iloc[0]['predictor']
subgroup_table=pd.DataFrame([{'model':k,'coef':all_est[k].loc[selected,'coef'],'lower_95':all_est[k].loc[selected,'ci_low'],'upper_95':all_est[k].loc[selected,'ci_high'],'p':all_est[k].loc[selected,'p']} for k in fits])
print('Candidate subgroup comparisons:');display(comp)
print('Selected predictor:',selected,'(smallest exploratory difference p-value, not pre-registered)');display(subgroup_table)
comp.to_csv(OUT/'subgroup_candidates.csv',index=False);subgroup_table.to_csv(OUT/'subgroup_coefficients.csv',index=False)

"""## 5. Part 2.2 — Deliberate omitted-variable stress test"""

# Duration is a plausible confound: correlated with credit amount and payment burden.
# Compare unpenalized GLMs with identical transformed feature values for included predictors.
removed='duration'; keep=[i for i,c in enumerate(infer_features) if c!=removed]
reduced_glm=glm_fit(Ztrain.iloc[:,keep],ytr)
red_est=estimates(reduced_glm,[infer_features[i] for i in keep])
# Four interpretable predictors; more may be shown if needed.
omit_features=['credit_amount','installment_rate','age','existing_credits']
omit_table=pd.DataFrame([{'predictor':k,'full_coef':all_est['Full'].loc[k,'coef'],'reduced_coef':red_est.loc[k,'coef'],'pct_change':100*(red_est.loc[k,'coef']-all_est['Full'].loc[k,'coef'])/abs(all_est['Full'].loc[k,'coef']) if abs(all_est['Full'].loc[k,'coef'])>1e-12 else np.nan} for k in omit_features])
print('Omitted:',removed);display(omit_table)
omit_table.to_csv(OUT/'omitted_variable.csv',index=False)

"""## 6. Part 2.3 — Confident mistakes and adversarial 50-row subset"""

wrong=((prob>=.75)&(yte.to_numpy()==0))|((prob<=.25)&(yte.to_numpy()==1))
wrong_ids=np.where(wrong)[0]
rs=np.random.RandomState(SEED)
selected_ids=rs.choice(wrong_ids,size=min(50,len(wrong_ids)),replace=False) if len(wrong_ids) else np.array([],dtype=int)
adv=test_df.iloc[selected_ids].copy();adv['predicted_probability']=prob[selected_ids]
adv['actual']=yte.iloc[selected_ids].to_numpy()
adv['predicted']=(prob[selected_ids]>=.5).astype(int)
adv_count=int(wrong.sum());adv_pct=100*adv_count/len(yte)
adv_group=adv['sex_group'].value_counts(normalize=True).mul(100)
full_group=test_df['sex_group'].value_counts(normalize=True).mul(100)
# Examine distributional deviations; report the most common among predeclared interpretable traits.
traits={'duration >= 24 months': lambda x:x.duration>=24,'amount >= 5000':lambda x:x.credit_amount>=5000,'age < 30':lambda x:x.age<30,'checking status A14':lambda x:x.checking_status=='A14','previous credit issue (A30/A31/A32)':lambda x:x.credit_history.isin(['A30','A31','A32'])}
trait_scores=[]
for name,fn in traits.items():
    rate=float(fn(adv).mean()*100) if len(adv) else np.nan
    baseline=float(fn(test_df).mean()*100)
    trait_scores.append((name,rate,baseline,rate-baseline if np.isfinite(rate) else np.nan))
trait_table=pd.DataFrame(trait_scores,columns=['trait','adversarial_pct','test_pct','difference_pp']).sort_values('difference_pp',ascending=False)
adv.to_csv(OUT/'adversarial_rows.csv',index=False)
print('All confident errors:',adv_count,f'({adv_pct:.2f}% of test set); sampled:',len(adv))
print('Sex distributions adversarial (%):',adv_group.to_dict(),'full test:',full_group.to_dict())
print('Age median adversarial:',adv.age.median() if len(adv) else np.nan,'test:',test_df.age.median())
display(trait_table)
trait_table.to_csv(OUT/'adversarial_traits.csv',index=False)

"""## 7. Part 2.4 — DP / EO / PP across thresholds"""

# The requested formulas are A/B ratios (not standard symmetric EO); follow the brief exactly.
# Group A = Female and Group B = Male. Decision 1 = approval proxy.
def div(a,b): return float(a/b) if b!=0 else np.nan
fair=[]
for threshold in np.round(np.arange(.05,.951,.1),2):
    prediction=(prob>=threshold).astype(int)
    data={}
    for label in ['Female','Male']:
        mask=(test_df.sex_group.to_numpy()==label)
        yt=yte.to_numpy()[mask];yh=prediction[mask]
        data[label]={'pos':yh.mean(),'tpr':yh[yt==1].mean() if (yt==1).any() else np.nan,'fpr':yh[yt==0].mean() if (yt==0).any() else np.nan,'ppv':yt[yh==1].mean() if (yh==1).any() else np.nan,'n':int(mask.sum())}
    A,B=data['Female'],data['Male']
    tpr_ratio=div(A['tpr'],B['tpr']);fpr_ratio=div(A['fpr'],B['fpr'])
    fair.append({'threshold':threshold,'DP':div(A['pos'],B['pos']),'EO':min(tpr_ratio,fpr_ratio) if np.isfinite(tpr_ratio) and np.isfinite(fpr_ratio) else np.nan,'PP':div(A['ppv'],B['ppv']),'accuracy':accuracy_score(yte,prediction),'female_selection':A['pos'],'male_selection':B['pos'],'female_TPR':A['tpr'],'male_TPR':B['tpr'],'female_FPR':A['fpr'],'male_FPR':B['fpr'],'female_PPV':A['ppv'],'male_PPV':B['ppv']})
fairness=pd.DataFrame(fair)
display(fairness.round(3))
fairness.to_csv(OUT/'fairness_thresholds.csv',index=False)
plt.figure(figsize=(9,6))
plt.scatter(fairness.DP,fairness.EO,s=65)
for _,r in fairness.iterrows():
    if np.isfinite(r.DP) and np.isfinite(r.EO):plt.annotate(f'{r.threshold:.2f}',(r.DP,r.EO),xytext=(4,4),textcoords='offset points',fontsize=8)
plt.axvline(1,ls='--',alpha=.4);plt.axhline(1,ls='--',alpha=.4)
plt.xlim(0,1.5);plt.ylim(0,1.5);plt.xlabel('Demographic parity ratio');plt.ylabel('Equalized odds ratio (assignment formula)')
plt.title('German Credit: fairness threshold sweep (seed 843)');plt.tight_layout();plt.savefig(OUT/'fairness_tradeoff.png',dpi=180);plt.show()
# Search threshold pairs with improvement in DP closeness to 1 and loss of EO closeness to 1.
tradeoffs=[]
for i,a in fairness.iterrows():
 for j,b in fairness.iterrows():
    if i==j or not all(np.isfinite([a.DP,a.EO,b.DP,b.EO])):continue
    dp_before=abs(1-a.DP);dp_after=abs(1-b.DP)
    eo_before=abs(1-a.EO);eo_after=abs(1-b.EO)
    if dp_after<dp_before and eo_after>eo_before:
        tradeoffs.append((dp_before-dp_after,eo_after-eo_before,a.threshold,b.threshold,a.DP,b.DP,a.EO,b.EO))
tradeoffs.sort(reverse=True)
tradeoff=tradeoffs[0] if tradeoffs else None
print('Example genuine trade-off:',tradeoff,'(None = no qualifying threshold pair; do not invent one)')
# Choose the observed threshold minimizing maximum deviation from parity, with accuracy as tiebreak.
f=fairness.copy();f['max_gap']=f[['DP','EO','PP']].apply(lambda r:max([abs(v-1) for v in r if np.isfinite(v)],default=np.inf),axis=1)
chosen=f.sort_values(['max_gap','accuracy'],ascending=[True,False]).iloc[0]
print('Defensible candidate:',chosen[['threshold','DP','EO','PP','accuracy']].to_dict())

"""## 8. Export evidence-based Word report, charts, and optional PDF"""

from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

def fmt(v,d=3):
    try:
        val=float(v)
    except (TypeError, ValueError):
        return 'undefined'
    return f'{val:.{d}f}' if pd.notna(val) and np.isfinite(val) else 'undefined'
def pct(v):return fmt(v,2)+'%'
def add_table(doc,df,round_digits=3):
    table=doc.add_table(rows=1,cols=len(df.columns));table.style='Light Shading Accent 1'
    for i,c in enumerate(df.columns):table.rows[0].cells[i].text=str(c)
    for _,r in df.iterrows():
        cells=table.add_row().cells
        for i,v in enumerate(r):cells[i].text=fmt(v,round_digits) if isinstance(v,(float,np.floating)) else str(v)
    doc.add_paragraph('')
def para(doc,s):doc.add_paragraph(s)

report=Document();sect=report.sections[0];sect.header.paragraphs[0].text='CSET485  |  AI and Society  |  Assignment 1'
normal=report.styles['Normal'];normal.font.name='Aptos';normal.font.size=Pt(10)
normal.paragraph_format.space_after=Pt(6)
