add_table(report,pd.DataFrame(cm,index=['OLS<median','OLS>=median'],columns=['Logit<.5','Logit>=.5']).reset_index(names='OLS vs Logistic'))
report.add_heading('Part 2.1 — Simpson’s paradox / subgroup divergence',1)
para(report,f'Using sex-coded subgroups Female (A) and Male (B), I compared continuous predictor coefficients for the pooled and separately fitted models. The largest exploratory intergroup coefficient difference among five specified candidates was {selected}. This is a difference hunt, not proof of Simpson’s paradox. The approximate between-group p-value is {fmt(float(comp.iloc[0].difference_p),4)}; multiple testing and model instability should be considered.')
add_table(report,subgroup_table)
